import re
from collections import defaultdict

def word_counts(text):
    # Use a regular expression to find all words, ignoring punctuation and case
    words = re.findall(r'\b\w+\b', text.lower())
    counts = defaultdict(int)
    for word in words:
        counts[word] += 1
    return dict(counts)
```

