def word_counts(text):
    import re
    # Remove punctuation and convert to lowercase
    cleaned_text = re.sub(r'[^\w\s]', '', text).lower()
    # Split into words
    words = cleaned_text.split()
    # Count occurrences
    counts = {}
    for word in words:
        if word in counts:
            counts[word] += 1
        else:
            counts[word] = 1
    return counts
```

```tests
assert word_counts("Hello! Hello?") == {'hello': 2}
assert word_counts("Python. Python!") == {'python': 2}
assert word_counts("Hello world. Hello world!") == {'hello': 2, 'world': 2}
assert word_counts("This is a test. This is a test!") == {'this': 2, 'is': 2, 'a': 2, 'test': 2}
```
